// The server's GEX rebuild (backend/app/intraday/gex_history.py) against the browser's gexProfile on the SAME real chain snapshot.
// backend/tests/fixtures/gex_parity.json holds the rows and the server's result (regenerated by backend/tests/unit/test_gex_parity.py).
import { describe, expect, it } from "vitest";
import fixture from "../../../backend/tests/fixtures/gex_parity.json";
import { gexLevels, gexProfile } from "../lib/gammaAnalysis";
import { gexUniverses } from "../lib/gexIntel";
import type { OptionChainRow } from "../lib/types";

const rows = fixture.rows as unknown as OptionChainRow[];
const at = Date.parse(fixture.at);
const rel = (a: number, b: number) => Math.abs(a - b) / Math.max(1e-9, Math.abs(b));

describe("server GEX reconstruction equals the browser's on one snapshot", () => {
  const prof = gexProfile(rows, fixture.spot, fixture.expiry, at, fixture.rate);
  const lv = gexLevels(prof, 5, true);
  const srv = fixture.server.full!;
  const ce = prof.rows.reduce((a, r) => a + (r.ce ?? 0), 0);
  const pe = prof.rows.reduce((a, r) => a + (r.pe ?? 0), 0);

  it("uses the same inputs: the same strikes, rate and expiry close", () => {
    expect(prof.rows.length).toBe(rows.length);
    expect(fixture.rate).toBe(0.06);
    expect(Number.isFinite(fixture.spot)).toBe(true);
  });
  it("call and put GEX totals agree within 2 %", () => {
    expect(rel(ce, srv.ce)).toBeLessThan(0.02);
    expect(rel(pe, srv.pe)).toBeLessThan(0.02);
  });
  it("net and absolute GEX agree within 5 % of the absolute exposure (net is a small difference of two large totals)", () => {
    expect(Math.abs((lv.netTotal ?? 0) - srv.net) / srv.abs).toBeLessThan(0.05);
    expect(rel(lv.absTotal ?? 0, srv.abs)).toBeLessThan(0.02);
  });
  it("the same strikes are used and the same walls and peak are found", () => {
    expect(lv.strikesUsed).toBe(srv.used);
    expect(lv.callWall).toBe(srv.call_wall);
    expect(lv.putWall).toBe(srv.put_wall);
    expect(lv.peak).toBe(srv.peak);
  });
  it("the gamma flip is within 30 index points", () => {
    expect(lv.flip).not.toBeNull();
    expect(Math.abs((lv.flip ?? 0) - (srv.flip ?? 0))).toBeLessThan(30);
  });
  it("the fixed and dynamic universes (ATM ±10) agree with the server's too", () => {
    const [fixed, dyn] = gexUniverses(rows, fixture.spot, fixture.expiry, at, srv.strikes ? fixture.server.fixed!.peak ?? null : null, 10);
    const s = fixture.server.dynamic!;
    expect(dyn!.listed).toBe(s.strikes);
    expect(dyn!.levels.strikesUsed).toBe(s.used);
    expect(rel(dyn!.levels.absTotal ?? 0, s.abs)).toBeLessThan(0.02);
    expect(fixed).toBeTruthy();
  });
});
